using System;using System.Globalization;using System.Windows;using System.Windows.Data;using System.Windows.Media;using RTXMediaMaster.Gui.Models;namespace RTXMediaMaster.Gui.Converters;public sealed class BoolToVisibilityConverter : IValueConverter{    public object Convert(object value, Type targetType, object parameter, CultureInfo culture)    {        bool b = value is bool v && v;        bool invert = parameter is string p && p.Equals("invert", StringComparison.OrdinalIgnoreCase);        return (b ^ invert) ? Visibility.Visible : Visibility.Collapsed;    }    public object ConvertBack(object value, Type targetType, object parameter, CultureInfo culture) =>        Binding.DoNothing;}public sealed class NullToVisibilityConverter : IValueConverter{    public object Convert(object value, Type targetType, object parameter, CultureInfo culture)    {        bool isNull = value is null;        bool invert = parameter is string p && p.Equals("invert", StringComparison.OrdinalIgnoreCase);        return (isNull ^ invert) ? Visibility.Collapsed : Visibility.Visible;    }    public object ConvertBack(object value, Type targetType, object parameter, CultureInfo culture) =>        Binding.DoNothing;}public sealed class StatusToBrushConverter : IValueConverter{    public object Convert(object value, Type targetType, object parameter, CultureInfo culture)    {        var status = value as string ?? string.Empty;        return status switch        {            "OK" => new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#34D399")!),            "WARN" => new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#FBBF24")!),            "MISSING" or "ERROR" => new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#F87171")!),            _ => new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#94A3B8")!),        };    }    public object ConvertBack(object value, Type targetType, object parameter, CultureInfo culture) =>        Binding.DoNothing;}public sealed class ItemStatusToBrushConverter : IValueConverter{    public object Convert(object value, Type targetType, object parameter, CultureInfo culture)    {        var s = value as ItemStatus? ?? ItemStatus.Pending;        return s switch        {            ItemStatus.Processing => new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#00D2FF")!),            ItemStatus.Completed => new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#34D399")!),            ItemStatus.Error or ItemStatus.Cancelled => new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#F87171")!),            ItemStatus.Analyzing => new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#FBBF24")!),            _ => new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#94A3B8")!),        };    }    public object ConvertBack(object value, Type targetType, object parameter, CultureInfo culture) =>        Binding.DoNothing;}public sealed class InverseBoolConverter : IValueConverter{    public object Convert(object value, Type targetType, object parameter, CultureInfo culture) =>        !(value is bool b && b);    public object ConvertBack(object value, Type targetType, object parameter, CultureInfo culture) =>        Binding.DoNothing;}public sealed class DoubleToPercentConverter : IValueConverter{    public object Convert(object value, Type targetType, object parameter, CultureInfo culture)    {        double d = value is double dd ? dd : (value is int ii ? ii : 0);        return $"{d:0}%";    }    public object ConvertBack(object value, Type targetType, object parameter, CultureInfo culture) =>        Binding.DoNothing;}public sealed class StepActiveConverter : IValueConverter{    public object Convert(object value, Type targetType, object parameter, CultureInfo culture)    {        int index = value is int i ? i : -1;        int target = int.TryParse(parameter?.ToString(), out var t) ? t : -1;        bool active = index >= target;        return active            ? new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#00D2FF")!)            : new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#7A8294")!);    }    public object ConvertBack(object value, Type targetType, object parameter, CultureInfo culture) =>        Binding.DoNothing;}public sealed class ProgressFillConverter : IMultiValueConverter{    public object Convert(object[] values, Type targetType, object parameter, CultureInfo culture)    {        double value = values[0] is double v ? v : (values[0] is int iv ? iv : 0);        double actualWidth = values[1] is double aw ? aw : 0;        double maximum = values[2] is double m ? m : (values[2] is int im ? im : 100);        if (maximum <= 0 || actualWidth <= 0) return 0d;        double pct = Math.Clamp(value / maximum, 0, 1);        return pct * actualWidth;    }    public object[] ConvertBack(object value, Type[] targetTypes, object parameter, CultureInfo culture) =>        throw new NotSupportedException();}public sealed class LogLevelToBrushConverter : IValueConverter{    public object Convert(object value, Type targetType, object parameter, CultureInfo culture)    {        var color = value switch        {            LogLevel.Error => "#FF6B6B",            LogLevel.Warning => "#FBBF24",            _ => "#34D399"        };        return new SolidColorBrush((Color)ColorConverter.ConvertFromString(color));    }    public object ConvertBack(object value, Type targetType, object parameter, CultureInfo culture) =>        Binding.DoNothing;}